/* Calls h's handler for xdg_surface request `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode xdg_surface
 * doesn't have. */
static inline status_t jwl_xdg_surface_dispatch_request(const struct jwl_xdg_surface_requests *h,
                                                        void *data, uint32_t self, uint32_t opcode,
                                                        const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_XDG_SURFACE_REQ_DESTROY:
        if (!h->destroy)
            return ERR_NOT_SUPPORTED;
        return h->destroy(data, self);
    case JWL_XDG_SURFACE_REQ_GET_TOPLEVEL:
        if (!h->get_toplevel)
            return ERR_NOT_SUPPORTED;
        return h->get_toplevel(data, self, a[0].n);
    case JWL_XDG_SURFACE_REQ_GET_POPUP:
        if (!h->get_popup)
            return ERR_NOT_SUPPORTED;
        return h->get_popup(data, self, a[0].n, a[1].o, a[2].o);
    case JWL_XDG_SURFACE_REQ_SET_WINDOW_GEOMETRY:
        if (!h->set_window_geometry)
            return ERR_NOT_SUPPORTED;
        return h->set_window_geometry(data, self, a[0].i, a[1].i, a[2].i, a[3].i);
    case JWL_XDG_SURFACE_REQ_ACK_CONFIGURE:
        if (!h->ack_configure)
            return ERR_NOT_SUPPORTED;
        return h->ack_configure(data, self, a[0].u);
    }
    return ERR_INVALID_ARGS;
}

/* Calls h's handler for xdg_surface event `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode xdg_surface
 * doesn't have. */
static inline status_t jwl_xdg_surface_dispatch_event(const struct jwl_xdg_surface_events *h,
                                                      void *data, uint32_t self, uint32_t opcode,
                                                      const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_XDG_SURFACE_EV_CONFIGURE:
        if (!h->configure)
            return ERR_NOT_SUPPORTED;
        return h->configure(data, self, a[0].u);
    }
    return ERR_INVALID_ARGS;
}


