/* Calls h's handler for xdg_toplevel request `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode xdg_toplevel
 * doesn't have. */
static inline status_t jwl_xdg_toplevel_dispatch_request(const struct jwl_xdg_toplevel_requests *h,
                                                         void *data, uint32_t self, uint32_t opcode,
                                                         const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_XDG_TOPLEVEL_REQ_DESTROY:
        if (!h->destroy)
            return ERR_NOT_SUPPORTED;
        return h->destroy(data, self);
    case JWL_XDG_TOPLEVEL_REQ_SET_PARENT:
        if (!h->set_parent)
            return ERR_NOT_SUPPORTED;
        return h->set_parent(data, self, a[0].o);
    case JWL_XDG_TOPLEVEL_REQ_SET_TITLE:
        if (!h->set_title)
            return ERR_NOT_SUPPORTED;
        return h->set_title(data, self, a[0].s);
    case JWL_XDG_TOPLEVEL_REQ_SET_APP_ID:
        if (!h->set_app_id)
            return ERR_NOT_SUPPORTED;
        return h->set_app_id(data, self, a[0].s);
    case JWL_XDG_TOPLEVEL_REQ_SHOW_WINDOW_MENU:
        if (!h->show_window_menu)
            return ERR_NOT_SUPPORTED;
        return h->show_window_menu(data, self, a[0].o, a[1].u, a[2].i, a[3].i);
    case JWL_XDG_TOPLEVEL_REQ_MOVE:
        if (!h->move)
            return ERR_NOT_SUPPORTED;
        return h->move(data, self, a[0].o, a[1].u);
    case JWL_XDG_TOPLEVEL_REQ_RESIZE:
        if (!h->resize)
            return ERR_NOT_SUPPORTED;
        return h->resize(data, self, a[0].o, a[1].u, a[2].u);
    case JWL_XDG_TOPLEVEL_REQ_SET_MAX_SIZE:
        if (!h->set_max_size)
            return ERR_NOT_SUPPORTED;
        return h->set_max_size(data, self, a[0].i, a[1].i);
    case JWL_XDG_TOPLEVEL_REQ_SET_MIN_SIZE:
        if (!h->set_min_size)
            return ERR_NOT_SUPPORTED;
        return h->set_min_size(data, self, a[0].i, a[1].i);
    case JWL_XDG_TOPLEVEL_REQ_SET_MAXIMIZED:
        if (!h->set_maximized)
            return ERR_NOT_SUPPORTED;
        return h->set_maximized(data, self);
    case JWL_XDG_TOPLEVEL_REQ_UNSET_MAXIMIZED:
        if (!h->unset_maximized)
            return ERR_NOT_SUPPORTED;
        return h->unset_maximized(data, self);
    case JWL_XDG_TOPLEVEL_REQ_SET_FULLSCREEN:
        if (!h->set_fullscreen)
            return ERR_NOT_SUPPORTED;
        return h->set_fullscreen(data, self, a[0].o);
    case JWL_XDG_TOPLEVEL_REQ_UNSET_FULLSCREEN:
        if (!h->unset_fullscreen)
            return ERR_NOT_SUPPORTED;
        return h->unset_fullscreen(data, self);
    case JWL_XDG_TOPLEVEL_REQ_SET_MINIMIZED:
        if (!h->set_minimized)
            return ERR_NOT_SUPPORTED;
        return h->set_minimized(data, self);
    }
    return ERR_INVALID_ARGS;
}

/* Calls h's handler for xdg_toplevel event `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode xdg_toplevel
 * doesn't have. */
static inline status_t jwl_xdg_toplevel_dispatch_event(const struct jwl_xdg_toplevel_events *h,
                                                       void *data, uint32_t self, uint32_t opcode,
                                                       const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_XDG_TOPLEVEL_EV_CONFIGURE:
        if (!h->configure)
            return ERR_NOT_SUPPORTED;
        return h->configure(data, self, a[0].i, a[1].i, a[2].a.data, a[2].a.size);
    case JWL_XDG_TOPLEVEL_EV_CLOSE:
        if (!h->close)
            return ERR_NOT_SUPPORTED;
        return h->close(data, self);
    case JWL_XDG_TOPLEVEL_EV_CONFIGURE_BOUNDS:
        if (!h->configure_bounds)
            return ERR_NOT_SUPPORTED;
        return h->configure_bounds(data, self, a[0].i, a[1].i);
    case JWL_XDG_TOPLEVEL_EV_WM_CAPABILITIES:
        if (!h->wm_capabilities)
            return ERR_NOT_SUPPORTED;
        return h->wm_capabilities(data, self, a[0].a.data, a[0].a.size);
    }
    return ERR_INVALID_ARGS;
}


/* ---- xdg_popup, upstream version 7: short-lived, popup surfaces for menus ---- */

#define JWL_XDG_POPUP_VERSION 7u

/* xdg_popup requests: the opcode, and the version each came in. */
#define JWL_XDG_POPUP_REQ_DESTROY          0u
#define JWL_XDG_POPUP_REQ_DESTROY_SINCE    1u
#define JWL_XDG_POPUP_REQ_GRAB             1u
#define JWL_XDG_POPUP_REQ_GRAB_SINCE       1u
#define JWL_XDG_POPUP_REQ_REPOSITION       2u
#define JWL_XDG_POPUP_REQ_REPOSITION_SINCE 3u
#define JWL_XDG_POPUP_REQ_DESTRUCTORS      0x00000001u

/* xdg_popup events: the opcode, and the version each came in. */
#define JWL_XDG_POPUP_EV_CONFIGURE          0u
#define JWL_XDG_POPUP_EV_CONFIGURE_SINCE    1u
#define JWL_XDG_POPUP_EV_POPUP_DONE         1u
#define JWL_XDG_POPUP_EV_POPUP_DONE_SINCE   1u
#define JWL_XDG_POPUP_EV_REPOSITIONED       2u
#define JWL_XDG_POPUP_EV_REPOSITIONED_SINCE 3u
#define JWL_XDG_POPUP_EV_DESTRUCTORS        0x00000000u

/* xdg_popup.error */
enum jwl_xdg_popup_error {
    JWL_XDG_POPUP_ERROR_INVALID_GRAB = 0, /* tried to grab after being mapped */
};

/* What the compositor does with each xdg_popup request: one handler per
 * message, or NULL (its dispatcher answers ERR_NOT_SUPPORTED). Each gets
 * the object's data (what libjwl's object map holds for it), its id
 * and the arguments the codec decoded and checked. */
struct jwl_xdg_popup_requests {
    status_t (*destroy)(void *data, uint32_t self);
    status_t (*grab)(void *data, uint32_t self, uint32_t seat, uint32_t serial);
    status_t (*reposition)(void *data, uint32_t self, uint32_t positioner, uint32_t token);
};

/* What a client does with each xdg_popup event: one handler per
 * message, or NULL (its dispatcher answers ERR_NOT_SUPPORTED). Each gets
 * the object's data (what libjwl's object map holds for it), its id
 * and the arguments the codec decoded and checked. */
struct jwl_xdg_popup_events {
    status_t (*configure)(void *data, uint32_t self, int32_t x, int32_t y, int32_t width,
                          int32_t height);
    status_t (*popup_done)(void *data, uint32_t self);
    status_t (*repositioned)(void *data, uint32_t self, uint32_t token);
};

/* xdg_popup.destroy, request 0, destroys the object: remove xdg_popup interface */
static inline status_t jwl_xdg_popup_destroy(struct jwl_conn *c, uint32_t self)
{
    return jwl_send(c, self, JWL_XDG_POPUP_REQ_DESTROY,
                    &jwl_xdg_popup_interface.requests[JWL_XDG_POPUP_REQ_DESTROY], NULL);
}

/* xdg_popup.grab, request 1: make the popup take an explicit grab */
static inline status_t jwl_xdg_popup_grab(struct jwl_conn *c, uint32_t self, uint32_t seat,
                                          uint32_t serial)
{
    const union jwl_arg jwl_a[] = {
        { .o = seat },
        { .u = serial },
    };
    return jwl_send(c, self, JWL_XDG_POPUP_REQ_GRAB,
                    &jwl_xdg_popup_interface.requests[JWL_XDG_POPUP_REQ_GRAB], jwl_a);
}

/* xdg_popup.reposition, request 2, since 3: recalculate the popup's location */
static inline status_t jwl_xdg_popup_reposition(struct jwl_conn *c, uint32_t self,
                                                uint32_t positioner, uint32_t token)
{
    const union jwl_arg jwl_a[] = {
        { .o = positioner },
        { .u = token },
    };
    return jwl_send(c, self, JWL_XDG_POPUP_REQ_REPOSITION,
                    &jwl_xdg_popup_interface.requests[JWL_XDG_POPUP_REQ_REPOSITION], jwl_a);
}

/* xdg_popup.configure, event 0: configure the popup surface */
static inline status_t jwl_xdg_popup_send_configure(struct jwl_conn *c, uint32_t self, int32_t x,
                                                    int32_t y, int32_t width, int32_t height)
{
    const union jwl_arg jwl_a[] = {
        { .i = x },
        { .i = y },
        { .i = width },
        { .i = height },
    };
    return jwl_send(c, self, JWL_XDG_POPUP_EV_CONFIGURE,
                    &jwl_xdg_popup_interface.events[JWL_XDG_POPUP_EV_CONFIGURE], jwl_a);
}

/* xdg_popup.popup_done, event 1: popup interaction is done */
static inline status_t jwl_xdg_popup_send_popup_done(struct jwl_conn *c, uint32_t self)
{
    return jwl_send(c, self, JWL_XDG_POPUP_EV_POPUP_DONE,
                    &jwl_xdg_popup_interface.events[JWL_XDG_POPUP_EV_POPUP_DONE], NULL);
}

/* xdg_popup.repositioned, event 2, since 3: signal the completion of a repositioned request */
static inline status_t jwl_xdg_popup_send_repositioned(struct jwl_conn *c, uint32_t self,
                                                       uint32_t token)
{
    const union jwl_arg jwl_a[] = {
        { .u = token },
    };
    return jwl_send(c, self, JWL_XDG_POPUP_EV_REPOSITIONED,
                    &jwl_xdg_popup_interface.events[JWL_XDG_POPUP_EV_REPOSITIONED], jwl_a);
}

/* Calls h's handler for xdg_popup request `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode xdg_popup
 * doesn't have. */
static inline status_t jwl_xdg_popup_dispatch_request(const struct jwl_xdg_popup_requests *h,
                                                      void *data, uint32_t self, uint32_t opcode,
                                                      const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_XDG_POPUP_REQ_DESTROY:
        if (!h->destroy)
            return ERR_NOT_SUPPORTED;
        return h->destroy(data, self);
    case JWL_XDG_POPUP_REQ_GRAB:
        if (!h->grab)
            return ERR_NOT_SUPPORTED;
        return h->grab(data, self, a[0].o, a[1].u);
    case JWL_XDG_POPUP_REQ_REPOSITION:
        if (!h->reposition)
            return ERR_NOT_SUPPORTED;
        return h->reposition(data, self, a[0].o, a[1].u);
    }
    return ERR_INVALID_ARGS;
}

/* Calls h's handler for xdg_popup event `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode xdg_popup
 * doesn't have. */
static inline status_t jwl_xdg_popup_dispatch_event(const struct jwl_xdg_popup_events *h,
                                                    void *data, uint32_t self, uint32_t opcode,
                                                    const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_XDG_POPUP_EV_CONFIGURE:
        if (!h->configure)
            return ERR_NOT_SUPPORTED;
        return h->configure(data, self, a[0].i, a[1].i, a[2].i, a[3].i);
    case JWL_XDG_POPUP_EV_POPUP_DONE:
        if (!h->popup_done)
            return ERR_NOT_SUPPORTED;
        return h->popup_done(data, self);
    case JWL_XDG_POPUP_EV_REPOSITIONED:
        if (!h->repositioned)
            return ERR_NOT_SUPPORTED;
        return h->repositioned(data, self, a[0].u);
    }
    return ERR_INVALID_ARGS;
}
